import itertools

def get_g(E, m):
    max_E = max([0] + list(E))
    return m * max_E - sum(E)

def find_min_N(m):
    for N in range(m):
        # E_i can range from -N to N. 
        # But wait, g = m*max(E) - sum(E). 
        # If max(E) = M, then sum(E) >= m*M - N.
        # Also sum(E) <= (m-1)*M.
        # So m*M - N <= (m-1)*M  =>  M <= N.
        # Also sum(E) >= m*M - N and each E_i <= M.
        # So we can bound E_i.

        # Let's find all states with g <= N.
        states = []
        for E in itertools.product(range(-N, N + 1), repeat=m-1):
            if get_g(E, m) <= N:
                states.append(E)

        S = set(states)
        while True:
            to_remove = set()
            for E in S:
                for k in range(1, m):
                    # Bob chooses k. Alice chooses s=1 or s=-1.
                    # E_j -> E_j + s for j >= k.
                    # The indices of E are 0 to m-2.
                    # k corresponds to index k-1.

                    s1_E = list(E)
                    for j in range(k-1, m-1):
                        s1_E[j] += 1
                    s1_E = tuple(s1_E)

                    s2_E = list(E)
                    for j in range(k-1, m-1):
                        s2_E[j] -= 1
                    s2_E = tuple(s2_E)

                    if s1_E not in S and s2_E not in S:
                        to_remove.add(E)
                        break

            if not to_remove:
                break
            S -= to_remove

        if S:
            return N
    return None

for m in range(2, 7):
    res = find_min_N(m)
    print(f"m={m}, N={res}")

def is_safe(S, y, m):
    x1_val = (S + sum((m - j) * y[j - 1] for j in range(1, m))) / m
    if x1_val != int(x1_val):
        return False
    x1 = int(x1_val)
    Y = [0] * m
    for i in range(1, m):
        Y[i] = Y[i - 1] + y[i - 1]
    for i in range(m):
        if x1 - Y[i] < 1:
            return False
    return True

def find_min_n(m):
    for n in range(1, 200):
        # Try all distributions with sum n
        distributions = []
        def get_distributions(current_dist, current_sum):
            if len(current_dist) == m:
                if current_sum == n:
                    distributions.append(tuple(current_dist))
                return
            for x in range(1, n - current_sum + 1):
                get_distributions(current_dist + [x], current_sum + x)
        get_distributions([], 0)
        if not distributions:
            continue

        # A state is (S, y_1, ..., y_{m-1})
        # S can change. Let's assume S is in [n-2, n+2].
        # y_i can be in [-n, n].
        # We want a set of safe states \mathcal{S}.
        # A state is safe if for all k, there's a d such that the next state is safe.
        # This is a fixed-point iteration.
        # Let's consider all states with S \in [n-2, n+2] and y_i \in [-n, n].
        states = []
        for S in range(max(1, n - 2), n + 3):
            for y_tuple in itertools.product(range(-n, n + 1), repeat=m-1):
                if is_safe(S, y_tuple, m):
                    states.append((S, y_tuple))

        # Fixed-point iteration
        while True:
            to_remove = []
            for S, y in states:
                is_winning = True
                for k in range(1, m):
                    d_possible = False
                    for d in [1, -1]:
                        S_new = S + d * (2 * k - m)
                        y_new = list(y)
                        y_new[k - 1] += 2 * d
                        if (S_new, tuple(y_new)) in states:
                            d_possible = True
                            break
                    if not d_possible:
                        is_winning = False
                        break
                if not is_winning:
                    to_remove.append((S, y))

            if not to_remove:
                break
            for r in to_remove:
                states.remove(r)

        # If any state with sum n is still in states, then n is enough.
        for S, y in states:
            # We need to check if this state actually has sum n.
            # The sum S of the state is the sum of the pebbles.
            if S == n:
                # Also check if there's a distribution with this S and y
                # that we actually started with.
                # Wait, any state (S, y) in states is a distribution with sum S.
                # So if S=n, it's one of the original distributions.
                return n
    return None

