import itertools

def get_states(m, current_sum, max_sum):
    if m == 1:
        return [[current_sum]]
    res = []
    for i in range(1, current_sum - (m - 1) + 1):
        for rest in get_states(m - 1, current_sum - i, max_sum):
            res.append([i] + rest)
    return res

def solve_for_m_optimized(m):
    s_max = m**2
    all_states = []
    for s in range(m, s_max + 1):
        all_states.extend(get_states(m, s, s_max))

    states = [tuple(s) for s in all_states]
    state_to_idx = {s: i for i, s in enumerate(states)}

    is_in_W = [True] * len(states)

    while True:
        changed = False
        for i, s in enumerate(states):
            if is_in_W[i]:
                is_still_winning = True
                for k in range(1, m):
                    m1 = list(s)
                    for j in range(k): m1[j] += 1
                    for j in range(k, m): m1[j] -= 1

                    m2 = list(s)
                    for j in range(k): m2[j] -= 1
                    for j in range(k, m): m2[j] += 1

                    m1_win = False
                    if all(y >= m for y in m1):
                        m1_win = True
                    else:
                        t1 = tuple(m1)
                        if t1 in state_to_idx:
                            if is_in_W[state_to_idx[t1]]:
                                m1_win = True

                    m2_win = False
                    if all(y >= m for y in m2):
                        m2_win = True
                    else:
                        t2 = tuple(m2)
                        if t2 in state_to_idx:
                            if is_in_W[state_to_idx[t2]]:
                                m2_win = True

                    if not m1_win and not m2_win:
                        is_still_winning = False
                        break

                if not is_still_winning:
                    is_in_W[i] = False
                    changed = True
        if not changed:
            break

    min_n = float('inf')
    for i, s in enumerate(states):
        if is_in_W[i]:
            min_n = min(min_n, sum(s))

    return min_n

for m in range(2, 7):
    print(f"m={m}, n={solve_for_m_optimized(m)}")

import itertools

def solve_for_m(m):
    limit = m + 1
    states = list(itertools.product(range(1, limit + 1), repeat=m))
    losing_set = set()

    changed = True
    while changed:
        changed = False
        for s in states:
            if s in losing_set:
                continue
            is_losing = False
            for k in range(1, m):
                s1 = list(s)
                for i in range(k): s1[i] += 1
                for i in range(k, m): s1[i] -= 1
                s2 = list(s)
                for i in range(k): s2[i] -= 1
                for i in range(k, m): s2[i] += 1

                def leads_to_losing(new_s):
                    if any(x == 0 for x in new_s):
                        return True
                    if any(x > limit for x in new_s):
                        return False
                    return tuple(new_s) in losing_set

                if leads_to_losing(s1) and leads_to_losing(s2):
                    is_losing = True
                    break
            if is_losing:
                losing_set.add(s)
                changed = True

    for n in range(1, m*m + 1):
        for s in itertools.product(range(1, n), repeat=m):
            if sum(s) == n:
                if s not in losing_set:
                    return n
    return None

