def find_min_N(m):
    # Looking for N such that there is a safe state
    # Try N from 0 to m*m (arbitrary high bound)
    for N in range(m*m + 1):
        states = []
        # Optimization: E_i is bounded by N
        # Since g = m*max(E) - sum(E) <= N
        # and sum(E) <= (m-1)*max(E)
        # m*max(E) - (m-1)*max(E) <= N => max(E) <= N.
        # Also sum(E) >= m*max(E) - N.
        for E in itertools.product(range(-N, N + 1), repeat=m-1):
            if get_g(E, m) <= N:
                states.append(E)

        S = set(states)
        while True:
            to_remove = set()
            for E in S:
                for k in range(1, m):
                    s1_E = list(E)
                    for j in range(k-1, m-1):
                        s1_E[j] += 1
                    s1_E = tuple(s1_E)

