def is_safe(S, y, m):
    x1_val = (S + sum((m - j) * y[j - 1] for j in range(1, m))) / m
    if x1_val != int(x1_val):
        return False
    x1 = int(x1_val)
    Y = [0] * m
    for i in range(1, m):
        Y[i] = Y[i - 1] + y[i - 1]
    for i in range(m):
        if x1 - Y[i] < 1:
            return False
    return True

def check_n_fixed(m, n):
    S_min = max(1, n - m)
    S_max = n + m
    y_range = range(-n, n + 1)

    states = []
    for S in range(S_min, S_max + 1):
        for y_tuple in itertools.product(y_range, repeat=m-1):
            if is_safe(S, y_tuple, m):
                states.append((S, y_tuple))

    while True:
        to_remove = []
        for S, y in states:
            is_winning = True
            for k in range(1, m):
                d_possible = False
                for d in [1, -1]:
                    S_new = S + d * (2 * k - m)
                    y_new = list(y)
                    y_new[k - 1] += 2 * d
                    if (S_new, tuple(y_new)) in states:
                        d_possible = True
                        break
                if not d_possible:
                    is_winning = False
                    break
            if not is_winning:
                to_remove.append((S, y))

        if not to_remove:
            break
        for r in to_remove:
            states.remove(r)

    for S, y in states:
        if S == n:
            return True
    return False

