import itertools

def get_states(m, current_sum, max_sum):
    if m == 1:
        return [[current_sum]]
    res = []
    for i in range(1, current_sum - (m - 1) + 1):
        for rest in get_states(m - 1, current_sum - i, max_sum):
            res.append([i] + rest)
    return res

def solve_for_m_optimized(m):
    # The sum can increase, but if we reach a state where all y_i >= m,
    # Alice wins. We search states with sum <= m^2.
    s_max = m**2
    all_states = []
    for s in range(m, s_max + 1):
        all_states.extend(get_states(m, s, s_max))

    states = [tuple(s) for s in all_states]
    state_to_idx = {s: i for i, s in enumerate(states)}

    is_in_W = [True] * len(states)

    # Iteratively remove states that are not winning
    while True:
        changed = False
        for i, s in enumerate(states):
            if is_in_W[i]:
                is_still_winning = True
                for k in range(1, m):
                    # Bob chooses k. Alice picks one of two groups.
                    # Group 1: B_1...B_k, Group 2: B_{k+1}...B_m

                    # Alice chooses Group 1:
                    # Move 1: y_1...y_k + 1, y_{k+1}...y_m - 1
                    m1 = list(s)
                    for j in range(k): m1[j] += 1
                    for j in range(k, m): m1[j] -= 1

                    # Alice chooses Group 2:
                    # Move 2: y_1...y_k - 1, y_{k+1}...y_m + 1
                    m2 = list(s)
                    for j in range(k): m2[j] -= 1
                    for j in range(k, m): m2[j] += 1

                    # Check if either move leads to a winning state.
                    # A state is winning if for ALL k, there exists a move to a winning state.
                    # Let's redefine: W is the set of winning states.
                    # s is in W if for all k, (m1 is in W OR m2 is in W).

                    def check_win(move):
                        if any(y <= 0 for y in move):
                            return False
                        if all(y >= m for y in move):
                            return True
                        t = tuple(move)
                        if t in state_to_idx:
                            return is_in_W[state_to_idx[t]]
                        return False

                    m1_win = check_win(m1)
                    m2_win = check_win(m2)

                    if not m1_win and not m2_win:
                        is_still_winning = False
                        break

                if not is_still_winning:
                    is_in_W[i] = False
                    changed = True
        if not changed:
            break

    min_n = float('inf')
    for i, s in enumerate(states):
        if is_in_W[i]:
            min_n = min(min_n, sum(s))

    return min_n

