import itertools

def solve_for_m(m):
    limit = m + 1
    states = list(itertools.product(range(1, limit + 1), repeat=m))
    losing_set = set()

    changed = True
    while changed:
        changed = False
        for s in states:
            if s in losing_set:
                continue
            is_losing = False
            for k in range(1, m):
                s1 = list(s)
                for i in range(k): s1[i] += 1
                for i in range(k, m): s1[i] -= 1
                s2 = list(s)
                for i in range(k): s2[i] -= 1
                for i in range(k, m): s2[i] += 1

                def leads_to_losing(new_s):
                    if any(x == 0 for x in new_s):
                        return True
                    if any(x > limit for x in new_s):
                        return False
                    return tuple(new_s) in losing_set

                if leads_to_losing(s1) and leads_to_losing(s2):
                    is_losing = True
                    break
            if is_losing:
                losing_set.add(s)
                changed = True

    for n in range(1, m*m + 1):
        for s in itertools.product(range(1, n), repeat=m):
            if sum(s) == n:
                if s not in losing_set:
                    return n
    return None

for m in range(2, 15):
    print(f"m={m}, n={solve_for_m(m)}")

